input.command:
cd <out>/h15-everwrite-inv-2
S=../plugin-everwrite/skills/everwrite
mkdir -p scripts && cp $S/scripts/tells.py scripts/tells.py
cat > scripts/lint-prose.js <<'EOF'
// Runs the everwrite checker (scripts/tells.py) over the English docs.
// docs/de and docs/fr are skipped: the checker's rules are English-only,
// and dashes and quote marks are normal punctuation in those languages.
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const path = require("node:path");

const SKIP = new Set([path.join("docs", "de"), path.join("docs", "fr")]);

function markdown(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) return SKIP.has(p) ? [] : markdown(p);
    return e.name.endsWith(".md") ? [p] : [];
  });
}

const files = ["README.md", ...markdown("docs").sort()];
const script = path.join(__dirname, "tells.py");

for (const py of ["python3", "python"]) {
  const r = spawnSync(py, [script, ...files], { stdio: "inherit" });
  if (r.error && r.error.code === "ENOENT") continue;
  process.exit(r.status === null ? 1 : r.status);
}
console.error("lint:prose needs Python 3.9 or later (python3 or python on PATH).");
process.exit(1);
EOF
node -e '
const fs=require("fs");
const p=JSON.parse(fs.readFileSync("package.json"));
p.scripts["lint:prose"]="node scripts/lint-prose.js";
fs.writeFileSync("package.json",JSON.stringify(p,null,2)+"\n")'
python3 - <<'EOF'
s=open("README.md").read()
q='> "Let me know if you have any questions" is a chatbot closer. Delete it.\n'
s=s.replace(q,'<!-- tells: off -->\n'+q+'<!-- tells: on -->\n')
open("README.md","w").write(s)
EOF
python3 - <<'EOF'
s=open(".github/workflows/ci.yml").read()
s+="""  prose:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - run: npm run lint:prose
"""
open(".github/workflows/ci.yml","w").write(s)
EOF
npm run lint:prose; echo exit=$?
mv docs/guide.md /tmp/g.md; npm run lint:prose | tail -2; echo exit=$?
printf '# X\n\nThis is a testament to seamless work.\n' > docs/new.md; npm run lint:prose | tail -2; echo "exit=${PIPESTATUS[0]}"; rm docs/new.md; mv /tmp/g.md docs/guide.md

